function [x_end, x_avg] = coil_lag(x0, u, tau, dt)
%COIL_LAG  One step dt of x' = (u - x)/tau with u held, from x0: (x at the end of the step, x averaged over it).
%   x0: real[1] (passed a plain number)
%   u: real[1] (passed a plain number)
%   tau: real[1] (passed a plain number)
%   dt: real[1] (passed a plain number)
%   returns x_end: real[1] (passed a plain number)
%   returns x_avg: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    x_end = 0;
    x_avg = 0;
    if (tau <= 0)
        x_end = u;
        x_avg = u;
    else
        e = exp(((-(dt)) / tau));
        x_end = (u + ((x0 - u) * e));
        x_avg = (u + ((((x0 - u) * tau) / dt) * (1 - e)));
    end
end
